css:
.sl-gallery-cinematic { padding-block: clamp(2.5rem, 5vw, 4rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-gallery-cinematic .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-gallery-cinematic .sl-cinematic-container { position: relative; border-radius: var(--smartlearn-radius, 1.5rem); overflow: hidden; min-height: 560px; display: flex; align-items: flex-end; padding: clamp(1.75rem, 4vw, 3rem); }
.sl-gallery-cinematic .sl-cinematic-media { position: absolute; inset: 0; z-index: 0; background-color: var(--smartlearn-card-bg); }
.sl-gallery-cinematic .sl-cinematic-container.is-playing .sl-cinematic-media { z-index: 10; }
.sl-gallery-cinematic .sl-cinematic-container.is-playing .sl-cinematic-info { opacity: 0; pointer-events: none; }
.sl-gallery-cinematic .sl-cinematic-poster { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-cinematic .sl-cinematic-overlay { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0, 0, 0, 0.88) 0%, rgba(0, 0, 0, 0.25) 55%, rgba(0, 0, 0, 0.1) 100%); pointer-events: none; transition: opacity 0.3s ease; }
.sl-gallery-cinematic .sl-cinematic-info { position: relative; z-index: 2; max-width: 600px; color: #ffffff; transition: opacity 0.3s ease; }
.sl-gallery-cinematic .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 76px; height: 76px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-cinematic .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-cinematic .sl-play-overlay:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 3px; }
.sl-gallery-cinematic .sl-close-video { position: absolute; top: 1rem; inset-inline-end: 1rem; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.sl-gallery-cinematic .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-cinematic .sl-badge { display: inline-block; padding: 0.3rem 0.85rem; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border-radius: 999px; font-size: 0.85rem; font-weight: 700; text-transform: uppercase; margin-bottom: 1rem; }
.sl-gallery-cinematic .sl-cinematic-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.85rem, 4vw, 3rem); font-weight: 800; margin: 0 0 0.85rem; color: #ffffff; }
.sl-gallery-cinematic .sl-cinematic-desc { font-size: 1.15rem; line-height: 1.6; margin: 0 0 1.5rem; color: rgba(255, 255, 255, 0.92); }
.sl-gallery-cinematic .sl-cinematic-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.sl-gallery-cinematic .sl-btn { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; padding: 0.75rem 2rem; border-radius: var(--smartlearn-radius, 0.5rem); font-weight: 700; text-decoration: none; transition: background-color 0.2s ease, color 0.2s ease; }
.sl-gallery-cinematic .sl-btn-primary { background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text) !important; border: 2px solid var(--smartlearn-btn-bg, var(--smartlearn-primary)); }
.sl-gallery-cinematic .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); }
.sl-gallery-cinematic .sl-btn-outline { background-color: transparent; color: #ffffff; border: 2px solid #ffffff; }
.sl-gallery-cinematic .sl-btn-outline:hover { background-color: #ffffff; color: #0f172a; }
.sl-gallery-cinematic .sl-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
@media (max-width: 767px) {
  .sl-gallery-cinematic .sl-cinematic-container { flex-direction: column; padding: 0; min-height: auto; }
  .sl-gallery-cinematic .sl-cinematic-media { position: relative; height: 280px; width: 100%; }
  .sl-gallery-cinematic .sl-cinematic-info { padding: 1.5rem; background-color: var(--smartlearn-card-bg); color: var(--smartlearn-text); width: 100%; max-width: none; }
  .sl-gallery-cinematic .sl-cinematic-title { color: var(--smartlearn-text); font-size: 1.75rem; }
  .sl-gallery-cinematic .sl-cinematic-desc { color: var(--smartlearn-text-muted); }
  .sl-gallery-cinematic .sl-cinematic-overlay { display: none; }
  .sl-gallery-cinematic .sl-btn-outline { border-color: var(--smartlearn-text); color: var(--smartlearn-text); }
  .sl-gallery-cinematic .sl-btn-outline:hover { background-color: var(--smartlearn-text); color: var(--smartlearn-bg); }
}
@media (prefers-reduced-motion: reduce) { .sl-gallery-cinematic .sl-cinematic-overlay, .sl-gallery-cinematic .sl-cinematic-info, .sl-gallery-cinematic .sl-play-overlay, .sl-gallery-cinematic .sl-btn { transition: none; } .sl-gallery-cinematic .sl-play-overlay:hover { transform: translate(-50%, -50%); } }

